import {
  ACHIEVEMENTS,
  ASCENSION_TIERS,
  ENDGAME_RELICS,
  PRESTIGE_DATA,
  SOUNDSCAPES,
  SOURCE_DATA,
  STORY_CHAPTERS,
  UI_TABS,
  UPGRADE_DATA
} from './data.js';
import { formatNumber } from './format.js';
import { translate as tr } from './i18n.js';

const $ = selector => document.querySelector(selector);

export function updateResources(engine) {
  const s = engine.state;
  $('#resource-breath').textContent = `${formatNumber(s.breath)} / ${formatNumber(s.maxBreath)}`;
  $('#resource-echo').textContent = formatNumber(s.echo);
  $('#resource-silence').textContent = formatNumber(s.silence);
  $('#resource-stardust').textContent = formatNumber(s.stardust);
  $('#resource-global').textContent = `×${engine.globalMultiplier().toFixed(2)}`;
  $('#cycle-level').textContent = `Lv.${s.eternalLevel}`;
}

export function updateCore(engine, renderer) {
  const s = engine.state;
  const preview = engine.projectedWave();
  const active = engine.activeChains(true).length;
  $('#frequency-value').textContent = String(s.frequency).padStart(2, '0');
  $('#frequency-slider').value = s.frequency;
  $('#combo-value').textContent = s.combo > 0 ? `×${engine.comboMultiplier().toFixed(1)}` : '—';
  $('#active-chain-count').textContent = String(engine.activeChains().length).padStart(2, '0');
  $('#projected-echo').textContent = formatNumber(preview.totalEcho);
  $('#projected-generations').textContent = formatNumber(preview.generations);
  $('#projected-silence').textContent = formatNumber(preview.silence);
  $('#polyphony-count').textContent = `${active} / ${s.polyphony}`;
  $('#emit-button').disabled = s.breath < 1;
  $('#ability-listen').disabled = s.silence < 5;
  $('#ability-stillness').disabled = s.silence < 10;
  $('#ability-replay').disabled = s.silence < 30 || !s.lastChain;
  $('#ability-chorus').disabled = s.breath < 10 || s.silence < 20;
  $('#prestige-button').disabled = s.silence < engine.getFinalCost();
  $('#prestige-cost').textContent = formatNumber(engine.getFinalCost());
  $('#prestige-gain').textContent = formatNumber(engine.getPrestigeGain());
  $('#frequency-hints').innerHTML = renderFrequencyHints(s.frequency, s.language);
  renderer.render(engine);
}

function renderFrequencyHints(frequency, language) {
  const relations = [
    { key: '干涉', low: 0, high: 4, tone: 'rose' },
    { key: '三度', low: 15, high: 25, tone: 'cyan' },
    { key: '五度', low: 32, high: 42, tone: 'violet' },
    { key: '八度', low: 47, high: 53, tone: 'amber' }
  ];
  return relations.map(relation => {
    const active = relation.low <= frequency && frequency <= relation.high;
    return `<span class="interval ${relation.tone}${active ? ' active' : ''}"><i></i>${tr(relation.key, language)} <small>${relation.low}–${relation.high}</small></span>`;
  }).join('');
}

export function renderNavigation(activeView, language, eternalLevel) {
  $('#view-navigation').innerHTML = UI_TABS.map(tab => `
    <button class="nav-item${activeView === tab.id ? ' active' : ''}" type="button" data-view="${tab.id}" aria-current="${activeView === tab.id ? 'page' : 'false'}">
      <span class="nav-icon" aria-hidden="true">${tab.icon}</span>
      <span>${tr(tab.label, language)}</span>
      ${tab.id === 'prestige' ? `<span class="nav-level">Lv.${eternalLevel}</span>` : ''}
    </button>
  `).join('');
}

export function renderPanel(engine, view) {
  const container = $('#panel-content');
  const { state: s } = engine;
  switch (view) {
    case 'upgrades': container.innerHTML = renderUpgrades(engine); break;
    case 'sources': container.innerHTML = renderSources(engine); break;
    case 'ambience': container.innerHTML = renderSoundscapes(engine); break;
    case 'achieve': container.innerHTML = renderAchievements(engine); break;
    case 'prestige': container.innerHTML = renderPrestige(engine); break;
    case 'expedition': container.innerHTML = renderStarChart(engine); break;
    case 'story': container.innerHTML = renderStory(engine); break;
    case 'settings': container.innerHTML = renderSettings(engine); break;
    default: container.innerHTML = '';
  }
  $('#panel-title').textContent = tr(UI_TABS.find(tab => tab.id === view)?.label || '观测站', s.language);
  $('#panel-kicker').textContent = tr('管理你的回响', s.language);
}

function renderUpgrades(engine) {
  const { state: s } = engine;
  return `<div class="panel-intro"><span class="section-kicker">${tr('振幅与共鸣', s.language)}</span><p>${tr('强化声音，让每一道回响走得更远。', s.language)}</p></div>
    <div class="upgrade-list">${UPGRADE_DATA.map((upgrade, index) => {
      const level = s.levels[upgrade.id];
      const cost = engine.getUpgradeCost(upgrade);
      const maxed = level >= upgrade.max;
      return `<article class="upgrade-card${maxed ? ' maxed' : ''}">
        <span class="upgrade-index">${String(index + 1).padStart(2, '0')}</span>
        <div class="upgrade-copy"><h3>${tr(upgrade.name, s.language)}</h3><p>${tr(upgrade.description, s.language)}</p><span class="upgrade-level">Lv. ${level}${Number.isFinite(upgrade.max) ? ` / ${upgrade.max}` : ''}</span></div>
        <button class="purchase-button" type="button" data-action="buy-upgrade" data-id="${upgrade.id}" ${maxed || s.echo < cost ? 'disabled' : ''}>${maxed ? tr('已满级', s.language) : `${formatNumber(cost)} ${tr('鸣响', s.language)}`}</button>
      </article>`;
    }).join('')}</div>`;
}

function renderSources(engine) {
  const { state: s } = engine;
  return `<div class="panel-intro"><span class="section-kicker">${tr('自动化网络', s.language)}</span><p>${tr('唤醒无人声源，让它们替你向深空呼喊。', s.language)}</p></div>
    <div class="source-list">${SOURCE_DATA.map((source, index) => {
      const item = s.sources[index];
      return `<article class="source-card${item.unlocked ? ' online' : ''}">
        <div class="source-heading"><span class="source-glyph">◉</span><div><h3>${tr('声源', s.language)} ${source.id}</h3><p>${item.unlocked ? tr('已激活', s.language) : tr('自动发声，无需消耗余息', s.language)}</p></div><b>${item.unlocked ? '●' : '○'}</b></div>
        ${item.unlocked ? `<label class="source-frequency">${tr('频率', s.language)} <output>${item.frequency}</output></label><input class="source-slider" data-source-frequency="${index}" type="range" min="0" max="100" value="${item.frequency}"><p class="source-timer">${tr('下一次', s.language)} ${Math.max(0, item.interval - item.timer).toFixed(1)}s</p>` : `<button class="purchase-button" data-action="unlock-source" data-index="${index}" ${s.echo < source.cost ? 'disabled' : ''}>${tr('解锁声源', s.language)} · ${formatNumber(source.cost)} ${tr('鸣响', s.language)}</button>`}
      </article>`;
    }).join('')}</div>`;
}

function renderSoundscapes(engine) {
  const { state: s } = engine;
  return `<div class="panel-intro"><span class="section-kicker">${tr('环境共鸣', s.language)}</span><p>${tr('用暗寂购买永久改变声场的回音。', s.language)}</p></div>
    <div class="soundscape-list">${SOUNDSCAPES.map((item, index) => {
      const active = s.soundscapes[index];
      return `<button class="soundscape-card${active ? ' online' : ''}" data-action="buy-soundscape" data-index="${index}" ${active || s.silence < item.cost ? 'disabled' : ''}>
        <span class="soundscape-glyph">${['⌂', '◈', '◉', '✧', '∞'][index]}</span><span class="soundscape-copy"><b>${tr(item.name, s.language)}</b><small>${tr(item.description, s.language)}</small></span><span class="soundscape-price">${active ? '✓' : `${formatNumber(item.cost)} ◌`}</span>
      </button>`;
    }).join('')}</div>`;
}

function renderAchievements(engine) {
  const { state: s } = engine;
  const unlocked = Object.values(s.achievements).filter(Boolean).length;
  return `<div class="panel-intro"><span class="section-kicker">${tr('已记录', s.language)} ${unlocked} / ${ACHIEVEMENTS.length}</span><p>${tr('每一次回响，都在星际档案中留下痕迹。', s.language)}</p></div>
    <div class="achievement-list">${ACHIEVEMENTS.map(item => {
      const achieved = s.achievements[item.id];
      return `<article class="achievement-card${achieved ? ' unlocked' : ''}"><span class="achievement-icon">${achieved ? item.icon : '·'}</span><div><h3>${achieved ? tr(item.name, s.language) : '???'}</h3><p>${tr(item.description, s.language)}</p></div><span class="achievement-status">${achieved ? '✦' : '—'}</span></article>`;
    }).join('')}</div>`;
}

function renderPrestige(engine) {
  const { state: s } = engine;
  return `<section class="cycle-card"><span class="section-kicker">${tr('轮回重置', s.language)} · ${s.eternalLevel + 1}</span><h3>${tr('让旧宇宙熄灭，让新宇宙听见。', s.language)}</h3>
    <p>${tr('长明会重置当前鸣响、暗寂、声源和普通升级。永久升级与成就会保留。', s.language)}</p>
    <div class="cycle-reward"><div><small>${tr('永久回响点', s.language)}</small><b>${formatNumber(s.echoPoints)}</b></div><div><small>${tr('下次可获得', s.language)}</small><b>+${formatNumber(engine.getPrestigeGain())}</b></div></div>
    <div class="cycle-reward"><div><small>${tr('需要暗寂', s.language)}</small><b>${formatNumber(engine.getFinalCost())}</b></div><div><small>${tr('星尘', s.language)}</small><b>${formatNumber(s.stardust)}</b></div></div></section>
    <div class="panel-intro"><span class="section-kicker">${tr('升级永久加成', s.language)}</span></div>
    <div class="upgrade-list">${PRESTIGE_DATA.map(item => {
      const level = s.permanent[item.id];
      const cost = engine.getPrestigeCost(item);
      return `<article class="upgrade-card compact"><span class="upgrade-index">✦</span><div class="upgrade-copy"><h3>${tr(item.name, s.language)}</h3><p>${tr(item.description, s.language)}</p><span class="upgrade-level">Lv. ${level}</span></div><button class="purchase-button" data-action="buy-prestige" data-id="${item.id}" ${s.echoPoints < cost ? 'disabled' : ''}>${formatNumber(cost)} EP</button></article>`;
    }).join('')}</div>`;
}

function renderStarChart(engine) {
  const { state: s } = engine;
  if (s.eternalLevel < 1) return `<section class="locked-chart"><span class="chart-orbit">✳</span><h3>${tr('星图尚未显现', s.language)}</h3><p>${tr('需要长明等级 1 才能观测星图。', s.language)}</p></section>`;
  const tierCards = ASCENSION_TIERS.map((tier, index) => {
    const complete = s.cosmicTier > index;
    const active = s.cosmicTier === index;
    const eligible = active && s.eternalLevel >= tier.eternalLevel && s.stardust >= tier.stardustCost;
    return `<article class="tier-card${complete ? ' complete' : active ? ' active' : ''}">
      <span class="tier-index">${String(index + 1).padStart(2, '0')}</span>
      <div class="tier-copy"><span class="section-kicker">${tr(tier.subtitle, s.language)}</span><h4>${tr(tier.name, s.language)}</h4><p>${tr(tier.description, s.language)}</p><small>${complete ? tr('层级已稳定', s.language) : tr(tier.objective, s.language)}</small></div>
      ${complete ? `<span class="tier-status">✓ ${tr('已完成', s.language)}</span>` : active ? `<button class="purchase-button tier-button" type="button" data-action="advance-tier" ${eligible ? '' : 'disabled'}>${tr('推进层级', s.language)} · ${tier.stardustCost} ✦</button>` : `<span class="tier-status">${tr('尚未抵达', s.language)}</span>`}
    </article>`;
  }).join('');
  return `<section class="star-chart-hero"><span class="section-kicker">${tr('深空遗物', s.language)}</span><h3>${tr('星图档案', s.language)}</h3><p>${tr('长明后解锁的深空遗物。', s.language)}</p><div class="stardust-balance">✦ ${formatNumber(s.stardust)} ${tr('星尘', s.language)}</div></section>
    <section class="ascension-section"><div class="panel-intro"><span class="section-kicker">${tr('远征层级', s.language)} · ${s.cosmicTier} / ${ASCENSION_TIERS.length}</span><p>${tr('每次推进都会重置当轮鸣响、暗寂与普通升级；长明、永久升级、遗物和航行日志将完整保留。', s.language)}</p></div><div class="tier-list">${tierCards}</div></section>
    <div class="relic-list">${ENDGAME_RELICS.map((relic, index) => {
      const level = s.relics[relic.id];
      const cost = (level + 1) * 3;
      return `<article class="relic-card"><span class="relic-glyph">${['◇', '✧', '⟡', '▤'][index]}</span><div class="relic-copy"><h3>${tr(relic.name, s.language)}</h3><p>${tr(relic.description, s.language)}</p><span class="upgrade-level">${tr('等级', s.language)} ${level} / ${relic.max}</span></div><button class="purchase-button" data-action="buy-relic" data-id="${relic.id}" ${level >= relic.max || s.stardust < cost ? 'disabled' : ''}>${level >= relic.max ? tr('已满级', s.language) : `${tr('升级遗物', s.language)} · ${cost} ✦`}</button></article>`;
    }).join('')}</div>
    <p class="softcap-note">${tr('一条回声链总产出的 8 段软上限会在安全阈值后趋于饱和。', s.language)}</p>`;
}

function renderStory(engine) {
  const { state: s } = engine;
  const unlocked = STORY_CHAPTERS.filter(chapter => engine.storyChapterUnlocked(chapter.id));
  const next = STORY_CHAPTERS.find(chapter => !engine.storyChapterUnlocked(chapter.id));
  return `<div class="panel-intro"><span class="section-kicker">${tr('航行日志', s.language)} · ${unlocked.length} / ${STORY_CHAPTERS.length}</span><p>${tr('信号记录已按观测顺序整理。尚未抵达的章节只显示下一项任务。', s.language)}</p></div>
    <div class="story-list">${unlocked.map((chapter, index) => `<article class="story-card"><div class="story-marker">${String(index + 1).padStart(2, '0')}</div><div class="story-copy"><h3>${tr(chapter.title, s.language)}</h3><p>${tr(chapter.text, s.language)}</p><small>✓ ${tr(chapter.objective, s.language)}</small></div></article>`).join('')}
    ${next ? `<article class="story-card story-next"><div class="story-marker">··</div><div class="story-copy"><span class="section-kicker">${tr('下一目标', s.language)}</span><h3>${tr(next.title, s.language)}</h3><p>${tr(next.objective, s.language)}</p></div></article>` : `<article class="story-card story-next"><div class="story-marker">✦</div><div class="story-copy"><span class="section-kicker">${tr('任务完成', s.language)}</span><h3>${tr('新的信号仍在等待。', s.language)}</h3><p>${tr('继续积累长明与星尘，完善遗物并探索终响之后的回声。', s.language)}</p></div></article>`}</div>`;
}

function renderSettings(engine) {
  const { state: s } = engine;
  return `<div class="panel-intro"><span class="section-kicker">${tr('设置与存档', s.language)}</span><p>${tr('调整观测站偏好，并安全管理本地进度。', s.language)}</p></div>
    <label class="setting-row"><span>${tr('主题', s.language)}</span><select id="theme-select"><option value="dark" ${s.theme === 'dark' ? 'selected' : ''}>${tr('暗色', s.language)}</option><option value="light" ${s.theme === 'light' ? 'selected' : ''}>Light</option></select></label>
    <label class="setting-row"><span>${tr('语言', s.language)}</span><select id="language-select"><option value="zh-CN" ${s.language === 'zh-CN' ? 'selected' : ''}>${tr('简体中文', s.language)}</option><option value="en-US" ${s.language === 'en-US' ? 'selected' : ''}>English</option></select></label>
    <div class="setting-row"><span>${tr('音效', s.language)}</span><button class="setting-toggle" data-action="toggle-sound">${s.soundEnabled ? '◖ ' + tr('开启', s.language) : '◗ ' + tr('关闭', s.language)}</button></div>
    <section class="save-tools"><h3>${tr('本地存档', s.language)}</h3><p>${tr('本地存档自动保存。导入会覆盖当前进度。', s.language)}</p><div class="setting-actions"><button data-action="export-save">${tr('导出存档', s.language)}</button><button data-action="import-save">${tr('导入存档', s.language)}</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></section>
    <button class="danger-button" data-action="hard-reset">${tr('清空全部数据', s.language)}</button>`;
}
