import { formatNumber } from './format.js';
import { translate } from './i18n.js';

function formatAmplitude(value) {
  if (value === 0) return '0';
  return value < 0.01 ? value.toExponential(2) : formatNumber(value);
}

export class WaveformRenderer {
  constructor(wrapper, canvas) {
    this.wrapper = wrapper;
    this.canvas = canvas;
    this.context = canvas.getContext('2d');
    this.width = 1;
    this.height = 1;
    this.viewportHeight = 1;
    this.pixelRatio = 1;
    this.theme = '';
    this.grid = document.createElement('canvas');
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(wrapper);
    window.addEventListener('resize', () => this.resize());
    this.resize();
  }

  resize() {
    this.pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
    const bounds = this.wrapper.getBoundingClientRect();
    this.width = Math.max(1, bounds.width);
    this.viewportHeight = Math.max(1, bounds.height);
    this.height = this.viewportHeight;
    this.canvas.width = Math.floor(this.width * this.pixelRatio);
    this.canvas.height = Math.floor(this.height * this.pixelRatio);
    this.canvas.style.width = `${this.width}px`;
    this.canvas.style.height = `${this.height}px`;
    this.context.setTransform(this.pixelRatio, 0, 0, this.pixelRatio, 0, 0);
    this.theme = '';
    this.renderGrid();
  }

  renderGrid() {
    this.theme = document.body.dataset.theme || 'dark';
    const style = getComputedStyle(document.body);
    const color = style.getPropertyValue('--grid').trim() || 'rgba(255,255,255,.045)';
    this.grid.width = this.canvas.width;
    this.grid.height = this.canvas.height;
    const context = this.grid.getContext('2d');
    context.setTransform(this.pixelRatio, 0, 0, this.pixelRatio, 0, 0);
    context.clearRect(0, 0, this.width, this.height);
    context.strokeStyle = color;
    context.lineWidth = 1;
    context.beginPath();
    for (let x = 0; x < this.width; x += 48) {
      context.moveTo(x, 0);
      context.lineTo(x, this.height);
    }
    for (let y = 0; y < this.height; y += 48) {
      context.moveTo(0, y);
      context.lineTo(this.width, y);
    }
    context.stroke();
  }

  render(engine) {
    if (this.theme !== (document.body.dataset.theme || 'dark')) this.renderGrid();
    const active = engine.activeChains();
    this.viewportHeight = Math.max(1, this.wrapper.clientHeight);
    const contentHeight = Math.max(this.viewportHeight, 28 + active.length * 52);
    if (contentHeight !== this.height) {
      this.height = contentHeight;
      this.canvas.height = Math.floor(contentHeight * this.pixelRatio);
      this.canvas.style.height = `${contentHeight}px`;
      this.context.setTransform(this.pixelRatio, 0, 0, this.pixelRatio, 0, 0);
      this.renderGrid();
    }

    const context = this.context;
    const style = getComputedStyle(document.body);
    const text = style.getPropertyValue('--wave-text').trim() || 'rgba(255,255,255,.55)';
    const row = style.getPropertyValue('--wave-row').trim() || 'rgba(255,255,255,.025)';
    context.clearRect(0, 0, this.width, this.height);
    context.drawImage(this.grid, 0, 0, this.width, this.height);

    if (!active.length) {
      context.fillStyle = text;
      context.font = '12px "Segoe UI", sans-serif';
      context.textAlign = 'center';
      context.fillText(translate('未发现回声', engine.state.language), this.width / 2, this.height / 2 - 8);
      context.fillText(translate('点击发声，唤醒第一道回响。', engine.state.language), this.width / 2, this.height / 2 + 16);
      return;
    }

    const rowHeight = Math.max(52, (this.height - 16) / active.length);
    active.forEach((chain, index) => {
      const top = 8 + index * rowHeight;
      const bottom = top + rowHeight - 8;
      const graphTop = top + 22;
      const graphHeight = Math.max(1, bottom - graphTop);
      const baseline = graphTop + graphHeight / 2;
      const sampleSpacing = Math.max(24, Math.min(56, this.width / 12));
      const sampleCount = chain.generations.length + 1;
      const currentRound = Math.min(sampleCount - 1, chain.elapsed / chain.interval);
      const visibleRounds = (this.width - 16) / sampleSpacing;
      const scrollStart = Math.max(0, currentRound - visibleRounds * 0.72);
      const currentX = Math.min(this.width - 8, 8 + (currentRound - scrollStart) * sampleSpacing);
      const sampleValue = round => round >= chain.generations.length
        ? chain.generations.at(-1)?.nextVibration || 0
        : chain.generations[round].vibration;
      const valueAt = round => {
        const index = Math.max(0, Math.min(sampleCount - 1, Math.floor(round)));
        const fraction = Math.max(0, Math.min(1, round - index));
        return sampleValue(index) * (1 - fraction)
          + sampleValue(Math.min(index + 1, sampleCount - 1)) * fraction;
      };
      const amplitudeAt = round =>
        Math.max(0, Math.min(1, valueAt(round) / chain.start)) * graphHeight * 0.42;

      context.fillStyle = row;
      context.fillRect(0, top, this.width, rowHeight - 4);
      context.fillStyle = this.frequencyColor(chain.frequency, 0.75);
      context.fillRect(0, top, 2, rowHeight - 4);

      if (sampleCount > 1) {
        context.beginPath();
        for (let x = 8; x <= currentX; x += 1) {
          const round = scrollStart + (x - 8) / sampleSpacing;
          const phase = round * Math.PI * 2;
          const y = baseline - amplitudeAt(round) * Math.sin(phase);
          if (x === 8) context.moveTo(x, y);
          else context.lineTo(x, y);
        }
        if (currentX > 8 && Math.floor(currentRound) === 0) {
          const y = baseline - amplitudeAt(currentRound) * Math.sin(currentRound * Math.PI * 2);
          context.lineTo(currentX, y);
        }
        context.strokeStyle = this.frequencyColor(chain.frequency, 0.2);
        context.lineWidth = 6;
        context.stroke();
        context.strokeStyle = this.frequencyColor(chain.frequency, 0.95);
        context.lineWidth = 1.6;
        context.stroke();
      }

      const currentValue = valueAt(currentRound);
      context.strokeStyle = this.frequencyColor(chain.frequency, 0.4);
      context.setLineDash([2, 4]);
      context.beginPath();
      context.moveTo(currentX, graphTop);
      context.lineTo(currentX, bottom);
      context.stroke();
      context.setLineDash([]);

      context.fillStyle = text;
      context.font = '10px "Segoe UI", sans-serif';
      context.textAlign = 'left';
      context.fillText(
        `f ${chain.frequency}  ·  n ${Math.floor(currentRound)}/${chain.generations.length}  ·  f(x) ${formatAmplitude(currentValue)}`,
        12,
        top + 14
      );
      context.textAlign = 'right';
      context.fillStyle = this.frequencyColor(chain.frequency, 0.9);
      context.fillText(`+${formatNumber(chain.earned)}`, this.width - 12, top + 14);
    });
  }

  frequencyColor(frequency, alpha) {
    const light = this.theme === 'light';
    const hue = 195 + frequency * 1.55;
    return `hsla(${hue}, 82%, ${light ? 43 : 65}%, ${alpha})`;
  }
}
